  public static func createMDP(
    _ fbb: inout FlatBufferBuilder,
    PROBLEM_IDOffset PROBLEM_ID: Offset,
    NAMEOffset NAME: Offset = Offset(),
    ENCOUNTER_STAGESVectorOffset ENCOUNTER_STAGES: Offset = Offset(),
    FLIGHT_TIME_BOUNDSVectorOffset FLIGHT_TIME_BOUNDS: Offset = Offset(),
    MAX_TOTAL_FLIGHT_TIME_DAYS: Double = 0.0,
    MAX_LAUNCH_C3_KM2_S2: Double = 0.0,
    MAX_TOTAL_DELTA_V_KM_S: Double = 0.0,
    DSM_MODE: mdpDsmMode = .none_,
    MAX_DSM_DELTA_V_KM_S: Double = 0.0,
    DSM_GRID_STEP_KM_S: Double = 0.0,
    MAX_REVOLUTIONS: UInt8 = 0,
    TRANSFER_DIRECTION: mdpTransferDirection = .either,
    OUTPUT_TIME_BIN_DAYS: Double = 0.0,
    MAX_THRUST_N: Double = 0.0,
    SPECIFIC_IMPULSE_S: Double = 0.0,
    DRY_MASS_KG: Double = 0.0,
    INITIAL_MASS_KG: Double = 0.0,
    EPHEMERIS_SOURCEOffset EPHEMERIS_SOURCE: Offset = Offset(),
    COMMENTOffset COMMENT: Offset = Offset()
  ) -> Offset {
    let __start = MDP.startMDP(&fbb)
    MDP.add(PROBLEM_ID: PROBLEM_ID, &fbb)
    MDP.add(NAME: NAME, &fbb)
    MDP.addVectorOf(ENCOUNTER_STAGES: ENCOUNTER_STAGES, &fbb)
    MDP.addVectorOf(FLIGHT_TIME_BOUNDS: FLIGHT_TIME_BOUNDS, &fbb)
    MDP.add(MAX_TOTAL_FLIGHT_TIME_DAYS: MAX_TOTAL_FLIGHT_TIME_DAYS, &fbb)
    MDP.add(MAX_LAUNCH_C3_KM2_S2: MAX_LAUNCH_C3_KM2_S2, &fbb)
    MDP.add(MAX_TOTAL_DELTA_V_KM_S: MAX_TOTAL_DELTA_V_KM_S, &fbb)
    MDP.add(DSM_MODE: DSM_MODE, &fbb)
    MDP.add(MAX_DSM_DELTA_V_KM_S: MAX_DSM_DELTA_V_KM_S, &fbb)
    MDP.add(DSM_GRID_STEP_KM_S: DSM_GRID_STEP_KM_S, &fbb)
    MDP.add(MAX_REVOLUTIONS: MAX_REVOLUTIONS, &fbb)
    MDP.add(TRANSFER_DIRECTION: TRANSFER_DIRECTION, &fbb)
    MDP.add(OUTPUT_TIME_BIN_DAYS: OUTPUT_TIME_BIN_DAYS, &fbb)
    MDP.add(MAX_THRUST_N: MAX_THRUST_N, &fbb)
    MDP.add(SPECIFIC_IMPULSE_S: SPECIFIC_IMPULSE_S, &fbb)
    MDP.add(DRY_MASS_KG: DRY_MASS_KG, &fbb)
    MDP.add(INITIAL_MASS_KG: INITIAL_MASS_KG, &fbb)
    MDP.add(EPHEMERIS_SOURCE: EPHEMERIS_SOURCE, &fbb)
    MDP.add(COMMENT: COMMENT, &fbb)
    return MDP.endMDP(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.PROBLEM_ID, fieldName: "PROBLEM_ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.NAME, fieldName: "NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ENCOUNTER_STAGES, fieldName: "ENCOUNTER_STAGES", required: false, type: ForwardOffset<Vector<ForwardOffset<MDPEncounterStage>, MDPEncounterStage>>.self)
    try _v.visit(field: VT.FLIGHT_TIME_BOUNDS, fieldName: "FLIGHT_TIME_BOUNDS", required: false, type: ForwardOffset<Vector<ForwardOffset<MDPFlightTimeBound>, MDPFlightTimeBound>>.self)
    try _v.visit(field: VT.MAX_TOTAL_FLIGHT_TIME_DAYS, fieldName: "MAX_TOTAL_FLIGHT_TIME_DAYS", required: false, type: Double.self)
    try _v.visit(field: VT.MAX_LAUNCH_C3_KM2_S2, fieldName: "MAX_LAUNCH_C3_KM2_S2", required: false, type: Double.self)
    try _v.visit(field: VT.MAX_TOTAL_DELTA_V_KM_S, fieldName: "MAX_TOTAL_DELTA_V_KM_S", required: false, type: Double.self)
    try _v.visit(field: VT.DSM_MODE, fieldName: "DSM_MODE", required: false, type: mdpDsmMode.self)
    try _v.visit(field: VT.MAX_DSM_DELTA_V_KM_S, fieldName: "MAX_DSM_DELTA_V_KM_S", required: false, type: Double.self)
    try _v.visit(field: VT.DSM_GRID_STEP_KM_S, fieldName: "DSM_GRID_STEP_KM_S", required: false, type: Double.self)
    try _v.visit(field: VT.MAX_REVOLUTIONS, fieldName: "MAX_REVOLUTIONS", required: false, type: UInt8.self)
    try _v.visit(field: VT.TRANSFER_DIRECTION, fieldName: "TRANSFER_DIRECTION", required: false, type: mdpTransferDirection.self)
    try _v.visit(field: VT.OUTPUT_TIME_BIN_DAYS, fieldName: "OUTPUT_TIME_BIN_DAYS", required: false, type: Double.self)
    try _v.visit(field: VT.MAX_THRUST_N, fieldName: "MAX_THRUST_N", required: false, type: Double.self)
    try _v.visit(field: VT.SPECIFIC_IMPULSE_S, fieldName: "SPECIFIC_IMPULSE_S", required: false, type: Double.self)
    try _v.visit(field: VT.DRY_MASS_KG, fieldName: "DRY_MASS_KG", required: false, type: Double.self)
    try _v.visit(field: VT.INITIAL_MASS_KG, fieldName: "INITIAL_MASS_KG", required: false, type: Double.self)
    try _v.visit(field: VT.EPHEMERIS_SOURCE, fieldName: "EPHEMERIS_SOURCE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.COMMENT, fieldName: "COMMENT", required: false, type: ForwardOffset<String>.self)
    _v.finish()
  }
